#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/traverser_iter.hpp> // for range-based traversal over traversers

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

namespace {

// -----------------------------------------------------------------------------
// Layout definition
// -----------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A and B are 3D: i x j x k, with k the innermost (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

// -----------------------------------------------------------------------------
// Parallel traversal helper
// -----------------------------------------------------------------------------
//
// This helper uses Noarr traversers for the actual iteration, but (optionally)
// employs OpenMP to split the outermost dimension across threads.
//
// - The outer loop is a range-based loop over the traverser. Each element of
//   the range is a traverser with the outermost dimension fixed.
// - Inside that loop, we call .for_each(f), which iterates the remaining
//   dimensions using Noarr.
// - With _OPENMP defined and -fopenmp enabled, the outer loop is parallel;
//   otherwise, this function falls back to a plain sequential .for_each.
//
// This keeps all index math and memory access strictly within Noarr.
//
template<class Traverser, class Func>
inline void parallel_for_each_outer_dim(Traverser trav, const Func &func) {
#ifdef _OPENMP
	#pragma omp parallel for schedule(static)
	for (auto sub_trav : trav) {
		// sub_trav has the outermost dimension fixed; .for_each iterates the rest
		sub_trav.for_each(func);
	}
#else
	trav.for_each(func);
#endif
}

// -----------------------------------------------------------------------------
// initialization function
// -----------------------------------------------------------------------------

void init_array(int n, auto A, auto B) {
	// A, B: i x j x k, all dimensions of length n
	using namespace noarr;

	auto trav = traverser(A, B);

	// Parallelize over outermost dimension ('i') when OpenMP is available.
	parallel_for_each_outer_dim(trav, [=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// Original: A[i][j][k] = B[i][j][k] =
		//   (DATA_TYPE) (i + j + (n - k)) * 10 / n;
		num_t value = num_t((i + j + (n - k)) * 10) / num_t(n);

		A[state] = value;
		B[state] = value;
	});
}

// -----------------------------------------------------------------------------
// computation kernel
// -----------------------------------------------------------------------------

[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	// A, B: i x j x k
	using namespace noarr;

	// Constants expressed once to make intent clear; the compiler will
	// constant-fold these.
	static constexpr num_t weight = num_t(0.125);
	static constexpr num_t two    = num_t(2.0);

	// Interior region: i, j, k in [1, n-2]
	//
	// This guarantees that all 6 neighbors used in the stencil
	// (±1 in each dimension) are inside the original domain.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain
	// tsteps times, without changing the physical layout of A and B.
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	// Traverse time dimension 't' explicitly using Noarr. For each logical
	// time step we then process the interior spatial domain. Within a single
	// time step we parallelize over the outermost spatial dimension.
	traverser(A, B)
		.order(time_bcast)
		.template for_dims<'t'>([&](auto t_trav) {
			// t_trav has 't' fixed and removed from its set of dimensions;
			// what remains are exactly the spatial dimensions i, j, k.
			auto inner = t_trav.order(interior);

			// -----------------------------------------------------------------
			// First sweep: update B from A (Jacobi-like)
			// -----------------------------------------------------------------
			//
			// We parallelize over the outermost spatial dimension ('i')
			// while letting Noarr control the inner loops ('j', 'k').
			//
			// Each point (i,j,k) in B depends only on values in A, so
			// all updates within this sweep are independent.
			//
			parallel_for_each_outer_dim(inner, [&](auto state) {
				using noarr::idx;

				// state contains indices for 'i', 'j', 'k'
				num_t center = A[state];

				num_t lap_i = A[state + idx<'i'>(1)] - two * center + A[state - idx<'i'>(1)];
				num_t lap_j = A[state + idx<'j'>(1)] - two * center + A[state - idx<'j'>(1)];
				num_t lap_k = A[state + idx<'k'>(1)] - two * center + A[state - idx<'k'>(1)];

				B[state] = weight * lap_i
				         + weight * lap_j
				         + weight * lap_k
				         + center;
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B
			// -----------------------------------------------------------------
			//
			// Same access pattern and parallelization strategy as above, but
			// swapping the roles of input (B) and output (A).
			//
			// There is a full barrier between the two parallel loops, so the
			// second sweep always observes a fully updated B.
			//
			parallel_for_each_outer_dim(inner, [&](auto state) {
				using noarr::idx;

				num_t center = B[state];

				num_t lap_i = B[state + idx<'i'>(1)] - two * center + B[state - idx<'i'>(1)];
				num_t lap_j = B[state + idx<'j'>(1)] - two * center + B[state - idx<'j'>(1)];
				num_t lap_k = B[state + idx<'k'>(1)] - two * center + B[state - idx<'k'>(1)];

				A[state] = weight * lap_i
				         + weight * lap_j
				         + weight * lap_k
				         + center;
			});
		});
	#pragma endscop
}

} // namespace

// -----------------------------------------------------------------------------
// main – benchmark harness (kept intact except for includes above)
// -----------------------------------------------------------------------------

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n = N;
	int tsteps = TSTEPS;

	// set lengths for spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
