		B[state] = value;
	});
}

// computation kernel
//
// Optimizations:
//  - Keep k as the innermost (contiguous) dimension for good spatial locality.
//  - Block the outer i-dimension using noarr::into_blocks to improve cache
//    reuse across planes while preserving the original iteration order.
//  - Split the interior in i into a "body" region (multiple of block size)
//    handled by blocked traversal and a "tail" region handled by a plain
//    traversal, so we correctly handle any n without assuming divisibility.
//  - Precompute index-state increments and reuse 2*center across axes to
//    reduce repeated computations while preserving the original formula.
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Precomputed ±1 index shifts for each spatial dimension.
	// These are compile-time constants and reused in every stencil evaluation.
	constexpr auto di = noarr::idx<'i'>(1);
	constexpr auto dj = noarr::idx<'j'>(1);
	constexpr auto dk = noarr::idx<'k'>(1);

	// Interior length (number of points per spatial axis that have all neighbors).
	const std::size_t interior_len = static_cast<std::size_t>(n - 2);

	// Spatial interior: i, j, k in [1, n-2]
	auto interior =
		noarr::slice<'i'>(1, interior_len) ^
		noarr::slice<'j'>(1, interior_len) ^
		noarr::slice<'k'>(1, interior_len);

	// Block size along the outer 'i' dimension.
	// 32 is a reasonable default for modern CPUs (cache- and vector-friendly),
	// but this can be tuned if needed.
	constexpr std::size_t I_BLOCK = 32;

	// Largest multiple of I_BLOCK not exceeding interior_len.
	// This is the "body" of the i-dimension that we can tile cleanly.
	const std::size_t i_block_body_len = (interior_len / I_BLOCK) * I_BLOCK;

	// Proto for the blocked "body" region in i:
	//   i_local in [0, i_block_body_len)
	// Applied on top of `interior` (which already starts i at 1), this
	// corresponds to original i indices [1, 1 + i_block_body_len).
	//
	// The into_blocks wrapper changes only the traversal structure
	// (adds a block index 'I' and intra-block index 'i') while keeping
	// states expressed in the original dimensions ('i', 'j', 'k'), so
	// neighbor accesses using idx<'i'>(±1) remain valid.
	auto i_body_proto =
		noarr::slice<'i'>(0, i_block_body_len) ^
		noarr::into_blocks<'i', 'I', 'i'>(I_BLOCK);

	// Proto for the remaining "tail" in i:
	//   i_local in [i_block_body_len, interior_len)
	// i_block_body_len may be 0 (no blocked part) or equal to interior_len
	// (no tail). Both cases are handled by the length becoming 0.
	auto i_tail_proto =
		noarr::slice<'i'>(i_block_body_len, interior_len - i_block_body_len);

	// One 7-point stencil sweep: src -> dst over the region described by `region_proto`.
	// `base_trav` is a traverser restricted to the full interior of a single timestep.
	auto sweep = [&](auto &src, auto &dst, auto base_trav, auto region_proto) {
		// Apply additional region-specific ordering (blocking or tail slicing).
		auto trav = base_trav.order(region_proto);

		trav.for_each([&](auto state) {
			// Center value
			num_t center = src[state];

			// Reuse 2 * center across all three axes, reducing multiplications.
			const num_t two_center = num_t(2.0) * center;

			// Discrete Laplacian components.
			// This is algebraically identical to:
			//   src[state + d] - 2*center + src[state - d]
			// for each dimension d in {di, dj, dk}, only factored to reuse
			// two_center. The order of operations matches the original form.
			num_t lap_i = src[state + di] - two_center + src[state - di];
			num_t lap_j = src[state + dj] - two_center + src[state - dj];
			num_t lap_k = src[state + dk] - two_center + src[state - dk];

			// Same numerical formula as in the original kernel:
			//   dst = 0.125 * lap_i + 0.125 * lap_j + 0.125 * lap_k + center;
			dst[state] =
				num_t(0.125) * lap_i +
				num_t(0.125) * lap_j +
				num_t(0.125) * lap_k +
				center;
		});
	};

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times.
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	traverser(A, B)
		.order(time_bcast)
		.template for_dims<'t'>([&](auto t_trav) {
			// t_trav has 't' fixed; we restrict it to the spatial interior.
			auto base_trav = t_trav.order(interior);

			// --- First sweep: update B from A over the whole interior ---

			// Blocked part along i (if any).
			if (i_block_body_len > 0) {
				sweep(A, B, base_trav, i_body_proto);
			}

			// Remaining tail along i (if interior_len not divisible by block size).
			if (i_block_body_len < interior_len) {
				sweep(A, B, base_trav, i_tail_proto);
			}

			// --- Second sweep: update A from B over the whole interior ---
			// Important: we must only start reading from B after all of B
			// has been computed in the first sweep, so we process the same
			// regions in the same order, but in a separate phase.

			if (i_block_body_len > 0) {
				sweep(B, A, base_trav, i_body_proto);
			}

			if (i_block_body_len < interior_len) {
				sweep(B, A, base_trav, i_tail_proto);
			}
		});
	#pragma endscop
}

} // namespace

