#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic 3D layout: i x j x k, with k the innermost (contiguous) dimension
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A and B are 3D: i x j x k, with k the innermost (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(int n, auto A, auto B) {
	// A, B: i x j x k, all dimensions of length n
	using namespace noarr;

	// Traverse the whole 3D domain once and initialize A and B identically.
	traverser(A, B).for_each([&](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// Original: A[i][j][k] = B[i][j][k] =
		//   (DATA_TYPE) (i + j + (n - k)) * 10 / n;
		const num_t value = num_t((i + j + (n - k)) * 10) / num_t(n);

		A[state] = value;
		B[state] = value;
	});
}

// computation kernel
//
// Optimizations compared to the original version:
//  - The artificial broadcasted time dimension ('t') was removed. Time
//    iteration is now done with a plain for-loop, while *all data loops*
//    (over i, j, k) still use Noarr traversers.
//    This avoids the overhead of repeatedly constructing and propagating
//    an extra dimension that is ignored by A and B.
//  - We build the interior traverser (excluding boundaries) once and reuse
//    it in all time steps instead of rebuilding it inside the time loop.
//  - Arithmetic inside the stencil was restructured to:
//      * compute 2*center only once per point and reuse for all three
//        coordinate directions,
//      * apply the factor 0.125 only once to the sum of the three
//        directional Laplacians.
//    These transformations reduce the number of floating-point multiplications
//    while preserving the mathematical stencil (up to standard FP round-off).
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Interior region: i, j, k in [1, n-2]
	// (boundary cells remain unchanged across all time steps)
	const auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Traverser restricted to the interior cells only
	auto interior_trav = traverser(A, B).order(interior);

	// Precompute coefficients as compile-time constants.
	//   alpha = 0.125
	//   beta  = 2.0
	// The update is:
	//   lap_i = A(i+1,j,k) + A(i-1,j,k) - beta * center
	//   lap_j = A(i,j+1,k) + A(i,j-1,k) - beta * center
	//   lap_k = A(i,j,k+1) + A(i,j,k-1) - beta * center
	//   B     = center + alpha * (lap_i + lap_j + lap_k)
	//
	// which is algebraically equivalent to the original formulation:
	//   lap_i = A(i+1,j,k) - 2*center + A(i-1,j,k)
	//   ...
	//   B     = 0.125 * lap_i + 0.125 * lap_j + 0.125 * lap_k + center
	constexpr num_t alpha = num_t(0.125);
	constexpr num_t beta  = num_t(2.0);

	#pragma scop
	for (int t = 0; t < tsteps; ++t) {
		// First sweep: update B from A over the interior
		interior_trav.for_each([&](auto state) {
			using noarr::idx;

			const num_t center      = A[state];
			const num_t two_center  = beta * center;

			const num_t lap_i =
				A[state + idx<'i'>(1)] +
				A[state - idx<'i'>(1)] -
				two_center;

			const num_t lap_j =
				A[state + idx<'j'>(1)] +
				A[state - idx<'j'>(1)] -
				two_center;

			const num_t lap_k =
				A[state + idx<'k'>(1)] +
				A[state - idx<'k'>(1)] -
				two_center;

			const num_t sum_lap = lap_i + lap_j + lap_k;

			B[state] = center + alpha * sum_lap;
		});

		// Second sweep: update A from B over the interior
		interior_trav.for_each([&](auto state) {
			using noarr::idx;

			const num_t center      = B[state];
			const num_t two_center  = beta * center;

			const num_t lap_i =
				B[state + idx<'i'>(1)] +
				B[state - idx<'i'>(1)] -
				two_center;

			const num_t lap_j =
				B[state + idx<'j'>(1)] +
				B[state - idx<'j'>(1)] -
				two_center;

			const num_t lap_k =
				B[state + idx<'k'>(1)] +
				B[state - idx<'k'>(1)] -
				two_center;

			const num_t sum_lap = lap_i + lap_j + lap_k;

			A[state] = center + alpha * sum_lap;
		});
	}
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n = N;
	int tsteps = TSTEPS;

	// set lengths for spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
