//   iteration to walk the domain block-by-block (tiles), which improves
//   cache locality and TLB behavior while preserving the memory layout.
// - The states seen in the lambda still contain only {'i','j','k','t'},
//   so all indexing expressions and neighbor accesses are unchanged
//   semantically; only the traversal order changes.
//
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Interior region: i, j, k in [1, n-2]
	// (we assume n >= 3 as in the original benchmark)
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	// ---------------------------------------------------------------------
	// Spatial blocking (tiling) in i and j
	//
	// We use into_blocks_dynamic so that we do *not* require (n-2) to be
	// divisible by the block size. Edge tiles are handled automatically.
	//
	// Because these proto-structures preserve the physical layout
	// (proto_preserves_layout == true), they can be safely used in
	// traverser.order(...). The states delivered to the lambdas still
	// only contain 'i','j','k','t', so the stencil code below is
	// unchanged except for the traversal order.
	//
	// Block sizes are compile-time constants (noarr::lit<...>) to allow
	// the library and compiler to optimize loop bounds.
	// ---------------------------------------------------------------------
	constexpr auto bi = noarr::lit<8>; // block size in 'i'
	constexpr auto bj = noarr::lit<8>; // block size in 'j'

	// Split 'i' into blocks: 'I' (block index) and 'i' (index within block),
	// with 'r' being the internal "is-present" flag dimension used by
	// into_blocks_dynamic. We then hoist 'I' to make it an outer loop.
	auto block_i =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(bi) ^
		noarr::hoist<'I'>();

	// Similarly for 'j': 'J' is the block index, 'j' is intra-block index,
	// 's' is the "is-present" flag. Again we hoist 'J' to make it outer.
	auto block_j =
		noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(bj) ^
		noarr::hoist<'J'>();

	// Combined spatial blocking proto-structure
	auto spatial_blocking = block_i ^ block_j;

	// Full traversal proto: time dimension, interior, then spatial blocking.
	// - time_bcast repeats the spatial domain tsteps times (dimension 't')
	// - interior restricts to 1..n-2 in each spatial dimension
	// - spatial_blocking reorganizes the interior traversal order into tiles
	auto traversal_proto = time_bcast ^ interior ^ spatial_blocking;

	// Pre-create constant index deltas used for neighbor accesses.
	// These are small, immutable state objects; defining them once
	// makes the intent explicit and avoids re-instantiating idx<...>
	// templates inside the inner loop.
	constexpr auto di = noarr::idx<'i'>(1);
	constexpr auto dj = noarr::idx<'j'>(1);
	constexpr auto dk = noarr::idx<'k'>(1);

	#pragma scop
	traverser(A, B)
		.order(traversal_proto)
		.template for_dims<'t'>([=](auto t_trav) {
			// t_trav has 't' fixed; remaining dimensions are traversed
			// in a cache-friendly tiled order over i and j, with k
			// still as the innermost (contiguous) dimension.

			// First sweep: update B from A
			t_trav.for_each([=](auto state) {
				// state contains 'i', 'j', 'k', and 't' (ignored by A/B)
				const num_t center = A[state];

				const num_t lap_i =
					A[state + di] - num_t(2.0) * center +
					A[state - di];
				const num_t lap_j =
					A[state + dj] - num_t(2.0) * center +
					A[state - dj];
				const num_t lap_k =
					A[state + dk] - num_t(2.0) * center +
					A[state - dk];

				B[state] = num_t(0.125) * lap_i
				         + num_t(0.125) * lap_j
				         + num_t(0.125) * lap_k
				         + center;
			});

			// Second sweep: update A from B
			t_trav.for_each([=](auto state) {
				const num_t center = B[state];

				const num_t lap_i =
					B[state + di] - num_t(2.0) * center +
					B[state - di];
				const num_t lap_j =
					B[state + dj] - num_t(2.0) * center +
					B[state - dj];
				const num_t lap_k =
					B[state + dk] - num_t(2.0) * center +
					B[state - dk];

				A[state] = num_t(0.125) * lap_i
				         + num_t(0.125) * lap_j
				         + num_t(0.125) * lap_k
				         + center;
			});
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n = N;
	int tsteps = TSTEPS;

	// set lengths for spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
